<div class='page-header mb-3'><h2 class='page-title'>إعدادات الترحيل المحاسبي</h2></div><div class='card table-responsive'><table class='table'><thead><tr><th>المفتاح</th><th>الحساب الحالي</th><th>تغيير الحساب</th></tr></thead><tbody><?php foreach($mappings as$m):?><tr><td><code><?=e($m['mapping_key'])?></code></td><td><?=e($m['account_code'].' - '.$m['name_ar'])?></td><td><form class='d-flex gap-2' method='post' action='/accounting/setup'><input type='hidden' name='_token' value='<?=e($csrfToken)?>'><input type='hidden' name='mapping_key' value='<?=e($m['mapping_key'])?>'><select class='form-select' name='account_id'><?php foreach($accounts as$a):?><option value='<?=e($a['id'])?>' <?=$a['id']===$m['account_id']?'selected':''?>><?=e($a['account_code'].' - '.$a['name_ar'])?></option><?php endforeach;?></select><button class='btn btn-primary'>حفظ</button></form></td></tr><?php endforeach;?></tbody></table></div>
